let wallpaper_changed = !1;
function chooseWallpaper() {
  if (0 == wallpaper_changed) {
    const e = document.createElement('input');
    e.type = 'file',
    e.accept = 'image/*',
    e.addEventListener(
      'change',
      function () {
        const t = e.files[0];
        if (t) {
          const e = new FileReader;
          e.onload = function (e) {
            const t = e.target.result;
            document.body.style.background = `url('${ t }') no-repeat center center fixed`,
            document.body.style.backgroundSize = 'cover',
            document.body.style.mozBackgroundSize = 'cover',
            document.body.style.oBackgroundSize = 'cover'
          },
          e.readAsDataURL(t),
          wallpaper_changed = !0
        }
      }
    ),
    e.click()
  } else document.body.style.background = 'url("/televisions/images/background.jpg") no-repeat center center fixed',
  document.body.style.backgroundSize = 'cover',
  document.body.style.mozBackgroundSize = 'cover',
  document.body.style.oBackgroundSize = 'cover',
  wallpaper_changed = !1
}
elements.BACKGROUND_BUTTON.addEventListener('click', chooseWallpaper);


